# shellmate shell integration for bash (generated by `shellmate init bash`; do not edit).
# glue protocol v1, see docs/glue.md and docs/spike-bash.md. Source it at the END of ~/.bashrc, after prompt tools.
[[ $- == *i* ]] || return 0
if (( BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4) )); then
  echo "shellmate: the bash integration needs bash >= 4.4 (this is $BASH_VERSION)" >&2
  return 0
fi

__shellmate_bin='@BIN@'
# a fresh conversation session per interactive shell (docs/conversation.md section 2); exported for `shellmate conversation`
export SHELLMATE_SESSION='@SESSION@'
__shellmate_runtime=${XDG_RUNTIME_DIR:-/tmp}/shellmate
[[ -d $__shellmate_runtime ]] || command mkdir -p -m 700 "$__shellmate_runtime" 2>/dev/null
__shellmate_status=0 __shellmate_last='' __shellmate_dur=0 __shellmate_t0='' __shellmate_last_hn=''
__shellmate_hist=() __shellmate_hist_len=10

# Last history entry without a subshell: `$(history 1)` forks, a redirect does not.
__shellmate_last_history() {
  local f=$__shellmate_runtime/$$.h
  history 1 >"$f"
  IFS= read -r __shellmate_hl <"$f"
  __shellmate_hl=${__shellmate_hl#"${__shellmate_hl%%[![:space:]]*}"}
  __shellmate_hn=${__shellmate_hl%%[![:digit:]]*}
  __shellmate_hl=${__shellmate_hl#"$__shellmate_hn"}
  __shellmate_hl=${__shellmate_hl#"${__shellmate_hl%%[![:space:]]*}"}
}
__shellmate_last_history
__shellmate_last_hn=$__shellmate_hn   # whatever was in the history file at startup did not just run

# PS0 runs before each command (bash >= 4.4); EPOCHREALTIME needs bash >= 5.0
if [[ -n ${EPOCHREALTIME-} ]]; then
  PS0=$PS0'${__shellmate_x[$((__shellmate_t0=${EPOCHREALTIME/./}))]:0:0}'
fi

# must run first among the prompt commands so that $? is still the user's command status
__shellmate_prompt() {
  local st=$?
  __shellmate_status=$st
  __shellmate_last_history
  # unchanged history number: nothing new was recorded (empty line, HISTCONTROL=ignorespace/ignoredups)
  if [[ -n $__shellmate_hn && $__shellmate_hn != "$__shellmate_last_hn" ]]; then
    __shellmate_last_hn=$__shellmate_hn
    __shellmate_last=$__shellmate_hl
    if [[ -n $__shellmate_t0 ]]; then
      __shellmate_dur=$(( (${EPOCHREALTIME/./} - __shellmate_t0) / 1000 ))
    fi
    __shellmate_hist+=("$st"$'\t'"$__shellmate_hl")
    (( ${#__shellmate_hist[@]} > __shellmate_hist_len )) && __shellmate_hist=("${__shellmate_hist[@]: -__shellmate_hist_len}")
  fi
  __shellmate_t0=''
  return $st
}
if [[ $(declare -p PROMPT_COMMAND 2>/dev/null) == "declare -a"* ]]; then
  PROMPT_COMMAND=(__shellmate_prompt "${PROMPT_COMMAND[@]}")
else
  PROMPT_COMMAND="__shellmate_prompt${PROMPT_COMMAND:+;$PROMPT_COMMAND}"
fi

__shellmate_run() {
  local action=$1 h out rc p
  local inf=$__shellmate_runtime/$$.in result=$__shellmate_runtime/$$.out
  # readline cleared the input line before running us: draw it again, then the output goes below it
  # (plan F, docs/spike-bash.md). ${PS1@P} is the already rendered prompt; only its last line is redrawn.
  p=${PS1@P}
  p=${p//[$'\001'$'\002']/}
  printf '\r\e[K%s%s\n' "${p##*$'\n'}" "$READLINE_LINE" >/dev/tty
  {
    printf 'v=1\0action=%s\0shell=bash\0shell_version=%s\0cwd=%s\0cursor=%s\0status=%s\0last_command=%s\0duration_ms=%s\0session=%s\0' \
      "$action" "$BASH_VERSION" "$PWD" "$READLINE_POINT" "$__shellmate_status" "$__shellmate_last" "$__shellmate_dur" "$SHELLMATE_SESSION"
    for h in "${__shellmate_hist[@]}"; do printf 'hist=%s\0' "$h"; done
    printf 'buffer=%s\0' "$READLINE_LINE"
  } >"$inf"
  "$__shellmate_bin" invoke <"$inf" >"$result"
  rc=$?
  : >"$inf"
  if (( rc == 0 )); then
    IFS= read -r -d '' out <"$result"
    READLINE_LINE=$out
    READLINE_POINT=${#out}
  fi
}

@BINDINGS@
